<script>
  export let $state = '';
  export let $derived = {};

  $effect(() => {
    const text = $state;
    $derived.wordCount = text.split(/\s+/).length;
    $derived.charCount = text.length;
    $derived.isLong = $derived.wordCount > 15;
  });

  function handleClear() {
    $state = '';
  }
</script>

<div>
  <input data-testid="text-input" type="text" bind:value={$state} />
  <button data-testid="clear-button" on:click={handleClear}>Clear</button>
  <div>
    <p data-testid="word-count">Words: {$derived.wordCount}</p>
    <p data-testid="char-count">Characters: {$derived.charCount}</p>
    <p data-testid="length-indicator">Status: {$derived.isLong ? 'Long text' : 'Short text'}</p>
  </div>
</div>
